{
  "query": "SELECT _q.* FROM (SELECT set_config('app.current_role', 'Administrador', true) AS r, set_config('app.current_user_id', (SELECT modulo1.fn_id_usuario_por_correo('administador.dev@gmail.com')::text), true) AS u) _rls CROSS JOIN LATERAL (SELECT (SELECT count(*) FROM modulo9.sensores_areas_asociadas WHERE id_sensor=536 AND fecha_asociacion < '2026-10-19 00:00:00+00') as asoc_ok, (SELECT count(*) FROM modulo9.calibraciones WHERE id_sensor=536 AND fecha_calibracion < '2026-10-19 00:00:00+00' AND offset_calibracion=-3.0 AND ganancia=1.0 AND valor_referencia=25.0) as cal_ok, (SELECT count(*) FROM modulo3.telemetrias WHERE id_sensor=536 AND timestamp_captura >= '2026-10-18 00:00:00+00' AND timestamp_captura < '2026-10-21 00:00:00+00') as contaminacion) _q WHERE _rls.r != '' AND _rls.u != ''"
}

